<div class="section"><div class="container"><h2><?=h($title)?></h2><div class="row g-3"><?php foreach ($packages as $p): ?><?php $available = isset($p['_available']) ? $p['_available'] : -1; ?><div class="col-md-4"><div class="card p-4"><h5><?=h(isset($p['name']) ? $p['name'] : '')?></h5><p><?=h(isset($p['description']) ? $p['description'] : '')?></p><b class="price"><?=money(isset($p['price']) ? $p['price'] : 0)?></b><?php if ($available !== -1): ?><p class="small <?= $available ? 'text-muted' : 'text-danger' ?>"><?= $available ? '剩余 ' . (int)$available : '已售罄' ?></p><?php endif; ?><form method="post" action="<?=h(url_to('index/shop/buyPackage', ['id' => (int)$p['id']]))?>" data-coupon-form data-coupon-type="dns_package" data-coupon-url="<?=h(url_to('index/order/coupon_preview'))?>"><?=csrf_field()?><input type="hidden" name="package_id" value="<?= (int)$p['id'] ?>"><?php include __DIR__ . '/../_coupon.php'; ?><button class="btn btn-primary mt-2" <?= $available === 0 ? 'disabled' : '' ?>><?= $available === 0 ? '已售罄' : '购买' ?></button></form></div></div><?php endforeach; ?></div></div></div>
